let language='en';
try{const saved=localStorage.getItem('hk-planning-language');if(saved==='en'||saved==='zh-Hant')language=saved}catch{}
function t(key,values={}){const value=translations[language][key]??translations.en[key]??key;return value.replace(/\{(\w+)\}/g,(_,k)=>values[k]??'')}
function number(value){return Number(value).toLocaleString(language==='en'?'en-HK':'zh-HK')}
function zoneName(group){return zoneNames[language][group]||group}
function languageCode(){return language==='en'?'en':'tc'}
function googleLanguage(){return language==='en'?'en':'zh-HK'}
function downloadPath(file){return `data/${language==='en'?'en/':''}${file}`}
